@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/reenie-beanie";

/* Light (faithful): alabaster cream page, charcoal ink, one deep evergreen panel, two sands
   for the contact band, citron-olive hairlines. Square, flat, light-weight type. */
:root {
  --background: #f6f4e8;
  --foreground: #272727;
  --card: #ffffff;
  --card-foreground: #272727;
  --popover: #fffefa;
  --popover-foreground: #272727;
  --primary: #104647;
  --primary-foreground: #fffefa;
  --secondary: #e9e7d6;
  --secondary-foreground: #272727;
  --muted: #d1ceb9;
  --muted-foreground: #74765e;
  --accent: #d1ceb9;
  --accent-foreground: #272727;
  --destructive: #b3261e;
  --destructive-foreground: #fffefa;
  --border: #8b8d73;
  --input: #8b8d73;
  --ring: #104647;
  --highlight: #bec2a5;
  --highlight-foreground: #272727;
  --glow: #9cabb9;
  --chart-1: #104647;
  --chart-2: #8b8d73;
  --chart-3: #405566;
  --chart-4: #d1ceb9;
  --chart-5: #272727;
  --sidebar: #e9e7d6;
  --sidebar-foreground: #272727;
  --sidebar-primary: #104647;
  --sidebar-primary-foreground: #fffefa;
  --sidebar-accent: #d1ceb9;
  --sidebar-accent-foreground: #272727;
  --sidebar-border: #8b8d73;
  --sidebar-ring: #104647;

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* not a base token: the handwriting face of captions, names and the formula board.
     Blocks read it with a fallback to the display face. */
  --typeface-hand: "Reenie Beanie", "Segoe Print", cursive;
  --radius: 0.125rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 2.75rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 3.5rem;
    --section-y: 6.5rem;
  }
}

/* Dark (sibling): a warm charcoal page with cream ink, the evergreen panel a step lighter,
   sands turned to dark olive-greys, the same citron hairlines. */
.dark {
  --background: #1f1f1c;
  --foreground: #f1efe3;
  --card: #2b2b27;
  --card-foreground: #f1efe3;
  --popover: #2b2b27;
  --popover-foreground: #f1efe3;
  --primary: #175e5f;
  --primary-foreground: #fffefa;
  --secondary: #2b2b26;
  --secondary-foreground: #f1efe3;
  --muted: #3a3932;
  --muted-foreground: #a7a990;
  --accent: #45443b;
  --accent-foreground: #f1efe3;
  --destructive: #e0675e;
  --destructive-foreground: #1f1f1c;
  --border: #6e705a;
  --input: #6e705a;
  --ring: #8fc3c2;
  --highlight: #c9cdb0;
  --highlight-foreground: #1f1f1c;
  --glow: #5f7385;
  --chart-1: #8fc3c2;
  --chart-2: #a7a990;
  --chart-3: #9cabb9;
  --chart-4: #45443b;
  --chart-5: #f1efe3;
  --sidebar: #2b2b26;
  --sidebar-foreground: #f1efe3;
  --sidebar-primary: #175e5f;
  --sidebar-primary-foreground: #fffefa;
  --sidebar-accent: #45443b;
  --sidebar-accent-foreground: #f1efe3;
  --sidebar-border: #6e705a;
  --sidebar-ring: #8fc3c2;
}
